import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Doctor and platform diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"operate/doctor.md","filePath":"operate/doctor.md","lastUpdated":1793054524000}'),o={name:"operate/doctor.md"};function r(n,e,l,p,d,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="doctor-and-platform-diagnostics" tabindex="-1">Doctor and platform diagnostics <a class="header-anchor" href="#doctor-and-platform-diagnostics" aria-label="Permalink to &quot;Doctor and platform diagnostics&quot;">​</a></h1><p>Run Doctor from the repository that owns <code>.neottia/config.yml</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Use an explicit root when automation starts elsewhere:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/repository</span></span></code></pre></div><h2 id="what-doctor-checks" tabindex="-1">What Doctor checks <a class="header-anchor" href="#what-doctor-checks" aria-label="Permalink to &quot;What Doctor checks&quot;">​</a></h2><p>Doctor reports:</p><ul><li>configuration validity and enabled capabilities;</li><li>expected lifecycle assets and installation receipt drift;</li><li>operating system, architecture, and runtime support;</li><li>installed native addon identity and integrity;</li><li>filesystem type, locality, and write access;</li><li>atomic no-replace publication;</li><li>hard-link and stable identity behavior;</li><li>file durability and namespace durability barriers.</li></ul><p>The filesystem probe runs in a private temporary area below the selected project. Doctor removes the area before it returns. Unsupported runtime tuples fail before probe files are created.</p><h2 id="machine-readable-output" tabindex="-1">Machine-readable output <a class="header-anchor" href="#machine-readable-output" aria-label="Permalink to &quot;Machine-readable output&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>The default project JSON report, without <code>--manifest</code>, uses deterministic formatting and omits machine-specific paths. Use it in CI to compare status and diagnostic codes. Do not parse the human prose.</p><h2 id="interpret-the-result" tabindex="-1">Interpret the result <a class="header-anchor" href="#interpret-the-result" aria-label="Permalink to &quot;Interpret the result&quot;">​</a></h2><ul><li><strong>Supported</strong> — the certified tuple and behavior probes passed. This is the expected state for filesystem-backed capabilities.</li><li><strong>Unsupported tuple</strong> — move the workload to a certified runtime, architecture, operating system, and local filesystem. Do not bypass the check.</li><li><strong>Missing native addon</strong> — reinstall from a trusted package source. An availability failure may use a source build when build tools are present.</li><li><strong>Integrity failure</strong> — stop. Reinstallation or investigation is required; integrity failures do not fall back to a source build.</li><li><strong>Receipt drift</strong> — inspect changed generated files or host entries before updating. Neottia will not overwrite them automatically.</li><li><strong>Probe failure</strong> — treat the reported publication, identity, link, or durability behavior as unsupported even if the filesystem name looks familiar.</li></ul><p>See the <a href="/projects/neottia/get-started/requirements#certified-repository-store-tuples">certified matrix</a>, <a href="/projects/neottia/repository-store">Repository Store reference</a>, and <a href="/projects/neottia/operate/troubleshooting">troubleshooting guide</a>.</p>',15)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
